"use client";

import { animate, motion, useMotionValue, useReducedMotion, useTransform, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, type PointerEvent, useEffect, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** Props for a slide to confirm. Pass `confirmed` to control it, or `defaultConfirmed` to let it hold its own state. */
export type SlideToConfirmProps = Omit<ComponentPropsWithoutRef<"div">, "children" | "onChange"> & {
  confirmed?: boolean;
  defaultConfirmed?: boolean;
  /** Called with `true` when the handle reaches the end. Set `confirmed` back to `false` to offer the slide again. */
  onConfirmedChange?: (confirmed: boolean) => void;
  /** Names the slider and shows in the track, such as "Slide to delete". */
  label?: string;
  confirmedLabel?: string;
  /** The share of the track a drag must cover before letting go confirms, from 0 to 1. */
  threshold?: number;
  /** How far one arrow key press moves the handle, out of 100. */
  step?: number;
  disabled?: boolean;
};

// Critically damped (2 × √400 = 40): a handle let go early returns with no bounce.
const RETURN: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
const FADE: Transition = { duration: 0.15 };

function ArrowGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="M3 8h10M9 4l4 4-4 4" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function CheckGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.75" aria-hidden="true" className="size-4">
      <path d="m3 8.5 3.25 3.25L13 5" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

const clamp = (value: number) => Math.min(1, Math.max(0, value));

/**
 * Confirms a serious action by dragging a handle to the end of a track. Let
 * go early and the handle slides back. The handle is a slider, so arrow keys
 * move it and reaching the end confirms.
 */
export function SlideToConfirm({
  confirmed,
  defaultConfirmed = false,
  onConfirmedChange,
  label = "Slide to confirm",
  confirmedLabel = "Confirmed",
  threshold = 0.9,
  step = 10,
  disabled = false,
  className,
  ...rootProps
}: SlideToConfirmProps) {
  const [ownConfirmed, setOwnConfirmed] = useState(defaultConfirmed);
  const done = confirmed ?? ownConfirmed;
  const [dragging, setDragging] = useState(false);
  const progress = useMotionValue(done ? 1 : 0);
  // Where the handle is heading, from 0 to 1. The motion value above may still be on its way there.
  const target = useRef(done ? 1 : 0);
  const railRef = useRef<HTMLSpanElement>(null);
  const handleRef = useRef<HTMLSpanElement>(null);
  const drag = useRef<{ pointerId: number; startX: number; startProgress: number; width: number } | null>(null);
  const reduceMotion = useReducedMotion();

  // The handle is 2.75rem wide inside 0.25rem of padding, so the rail it rides ends 3rem short of the track.
  // Clamped: a fast flick hands its speed to the spring, and the handle must never leave the track.
  const left = useTransform(progress, (p) => `${clamp(p) * 100}%`);
  const fillWidth = useTransform(progress, (p) => `calc(${clamp(p)} * (100% - 3.25rem) + 3.25rem)`);
  const labelOpacity = useTransform(progress, [0, 0.6], [1, 0]);

  const moveTo = (next: number, follow = false) => {
    target.current = next;
    // Written straight onto the handle: a React state update per pointer move would re-render on every sample.
    const percent = Math.round(next * 100);
    handleRef.current?.setAttribute("aria-valuenow", String(percent));
    handleRef.current?.setAttribute("aria-valuetext", `${percent}%`);
    if (follow || reduceMotion) {
      progress.stop();
      progress.set(next);
    } else {
      animate(progress, next, RETURN);
    }
  };

  // Follows the confirmed state, so a controlled reset sends the handle home.
  useEffect(() => {
    const next = done ? 1 : 0;
    if (target.current === next) return;
    target.current = next;
    if (reduceMotion) progress.set(next);
    else animate(progress, next, RETURN);
  }, [done, progress, reduceMotion]);

  const confirm = () => {
    moveTo(1);
    if (confirmed === undefined) setOwnConfirmed(true);
    onConfirmedChange?.(true);
  };

  const locked = disabled || done;

  function onPointerDown(event: PointerEvent<HTMLSpanElement>) {
    if (locked || event.button !== 0 || drag.current) return;
    const width = railRef.current?.getBoundingClientRect().width ?? 0;
    if (width <= 0) return;
    progress.stop();
    drag.current = { pointerId: event.pointerId, startX: event.clientX, startProgress: progress.get(), width };
    event.currentTarget.setPointerCapture?.(event.pointerId);
    setDragging(true);
  }

  function onPointerMove(event: PointerEvent<HTMLSpanElement>) {
    const active = drag.current;
    if (!active || active.pointerId !== event.pointerId) return;
    // No spring while the handle is held: it must stay under the finger.
    moveTo(clamp(active.startProgress + (event.clientX - active.startX) / active.width), true);
  }

  function endDrag(event: PointerEvent<HTMLSpanElement>, cancelled: boolean) {
    const active = drag.current;
    if (!active || active.pointerId !== event.pointerId) return;
    drag.current = null;
    setDragging(false);
    if (!cancelled && progress.get() >= threshold) confirm();
    else moveTo(0);
  }

  function onKeyDown(event: KeyboardEvent<HTMLSpanElement>) {
    if (locked) return;
    const value = Math.round(target.current * 100);
    const forward = event.key === "ArrowRight" || event.key === "ArrowUp";
    const back = event.key === "ArrowLeft" || event.key === "ArrowDown";
    const home = event.key === "Home" || event.key === "Escape";
    if (!forward && !back && !home && event.key !== "End") return;
    const next = forward ? value + step : back ? value - step : home ? 0 : 100;
    event.preventDefault();
    if (next >= 100) confirm();
    else moveTo(Math.max(0, next) / 100);
  }

  return (
    <div
      {...rootProps}
      data-confirmed={done}
      className={cn(
        // 3.375rem: the 1px border and 0.25rem of padding leave the handle 2.75rem (44px).
        "relative isolate h-13.5 w-full select-none overflow-hidden rounded-full border border-border bg-muted text-sm font-medium",
        disabled && "opacity-50",
        className,
      )}
    >
      {/* One element changes width a frame. A scale would squash the rounded end that hugs the handle. */}
      <motion.span aria-hidden="true" style={{ width: fillWidth }} className="absolute inset-y-0 left-0 -z-10 rounded-full bg-primary/15" />
      <motion.span
        aria-hidden="true"
        style={{ opacity: done ? 0 : labelOpacity }}
        className="absolute inset-0 flex items-center justify-center px-14 text-muted-foreground"
      >
        <span className="truncate">{label}</span>
      </motion.span>
      <motion.span
        aria-hidden="true"
        initial={false}
        animate={{ opacity: done ? 1 : 0 }}
        transition={FADE}
        className="absolute inset-0 flex items-center justify-center px-14 text-foreground"
      >
        <span className="truncate">{confirmedLabel}</span>
      </motion.span>
      <span ref={railRef} className="absolute inset-y-1 left-1 right-12">
        <motion.span
          ref={handleRef}
          role="slider"
          tabIndex={disabled ? -1 : 0}
          aria-label={label}
          aria-orientation="horizontal"
          aria-valuemin={0}
          aria-valuemax={100}
          // React writes these when the confirmed state changes. Between those, `moveTo` keeps them current.
          aria-valuenow={done ? 100 : 0}
          aria-valuetext={done ? confirmedLabel : "0%"}
          aria-disabled={locked || undefined}
          data-dragging={dragging}
          style={{ left }}
          onPointerDown={onPointerDown}
          onPointerMove={onPointerMove}
          onPointerUp={(event) => endDrag(event, false)}
          onPointerCancel={(event) => endDrag(event, true)}
          onLostPointerCapture={(event) => endDrag(event, true)}
          onKeyDown={onKeyDown}
          // Leaving the handle part way is the keyboard's way of letting go early.
          onBlur={() => {
            if (!done && !drag.current && target.current > 0) moveTo(0);
          }}
          className={cn(
            "absolute inset-y-0 flex aspect-square touch-none items-center justify-center rounded-full bg-primary text-primary-foreground shadow-sm outline-none",
            "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
            locked ? "cursor-default" : "cursor-grab data-[dragging=true]:cursor-grabbing",
          )}
        >
          {done ? <CheckGlyph /> : <ArrowGlyph />}
        </motion.span>
      </span>
      <span className="sr-only" role="status">
        {done ? confirmedLabel : ""}
      </span>
    </div>
  );
}
